mapper.select:
SELECT id, event_id AS eventId, user_id AS userId, username, event_type AS eventType,
       success, remote_login AS remoteLogin, previous_ip AS previousIp,
       ip_address AS ipAddress, user_agent AS userAgent, failure_reason AS failureReason,
       occurred_at AS occurredAt, created_at AS createdAt
FROM login_audit_log

    AND user_id = #{userId}
    AND username LIKE CONCAT('%', #{username}, '%')
    AND event_type = #{eventType}
    AND success = #{success}
    AND remote_login = #{remoteLogin}
    AND occurred_at >= CONCAT(#{startDate}, ' 00:00:00')
    AND occurred_at <= CONCAT(#{endDate}, ' 23:59:59')

ORDER BY occurred_at DESC, id DESC
